mapper.select:
SELECT rp.*, e.name as employee_name, e.employee_no, d.unit_name as dept_name, CASE WHEN d.unit_type = 2 THEN d.unit_name WHEN p1.unit_type = 2 THEN p1.unit_name WHEN p2.unit_type = 2 THEN p2.unit_name WHEN p3.unit_type = 2 THEN p3.unit_name ELSE NULL END as company_name FROM hr_reward_punish rp LEFT JOIN hr_employee e ON rp.employee_id = e.id LEFT JOIN org_unit d ON e.dept_id = d.id LEFT JOIN org_unit p1 ON d.parent_id = p1.id LEFT JOIN org_unit p2 ON p1.parent_id = p2.id LEFT JOIN org_unit p3 ON p2.parent_id = p3.id WHERE 1 = 1
AND e.name LIKE CONCAT('%', #{employeeName}, '%')
AND rp.type = #{type}
AND rp.status = #{status}
ORDER BY rp.created_time DESC
